    timelineAnalysis,
    {
      generated: baselineGen,
      spec: baselineSpec,
      report: baselineReport,
      revision: 1,
      findingsHistory: [repairFindings(baselineReport, baselineSpec)],
    },
    { jobId: 'job-tl-1', specId: 'spec-tl-1' },
    'test-live',
    () => new Date('2026-01-01T00:00:00.000Z'),
