  const weakening = outBad.report.checks.find((c) => c.id === 'repair.no-weakening');
  assert.ok(weakening);
  assert.equal(weakening.passed, false);
  assert.equal(outBad.report.publishable, false);
  void assembleTimelineFromGen;
});

